import {de,en,tr,legal} from './content.js';
const dictionaries={de,en,tr};
const storageKey='eleven-global-mockup-v1';
const fallback={version:1,language:'de',accent:'#c8a567',notes:'',overrides:{de:{},en:{},tr:{}}};
let state=structuredClone(fallback),editing=false,selectedKey='',market=1,toastTimer;
const legalDefaults={};
for(const [slug,page] of Object.entries(legal)){legalDefaults[`legal.${slug}.title`]=page.title;legalDefaults[`legal.${slug}.intro`]=page.intro;page.rows.forEach(([label,body],i)=>{legalDefaults[`legal.${slug}.${i}.label`]=label;legalDefaults[`legal.${slug}.${i}.body`]=body;});}
const knownKeys=new Set([...Object.keys(de),...Object.keys(legalDefaults)]);
function validateState(raw){
 if(!raw||typeof raw!=='object'||raw.version!==1||!['de','en','tr'].includes(raw.language)||!/^#[0-9a-f]{6}$/i.test(raw.accent)||typeof raw.notes!=='string'||raw.notes.length>10000)throw Error('Ungültiges Entwurfsformat.');
 const next={version:1,language:raw.language,accent:raw.accent,notes:raw.notes,overrides:{de:{},en:{},tr:{}}};
 for(const lang of ['de','en','tr']){const values=raw.overrides?.[lang];if(!values||typeof values!=='object'||Array.isArray(values))throw Error('Textänderungen fehlen.');for(const [key,value] of Object.entries(values)){if(!knownKeys.has(key)||typeof value!=='string'||value.length>10000)throw Error('Ungültige Textänderung.');next.overrides[lang][key]=value;}}
 return next;
}
let storageBlocked=false;
try{const saved=localStorage.getItem(storageKey);if(saved)state=validateState(JSON.parse(saved));}catch{storageBlocked=true;}
const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function t(key){const lang=key.startsWith('legal.')?'de':state.language;return state.overrides[lang][key]??dictionaries[lang][key]??de[key]??legalDefaults[key]??key;}
function txt(key,tag='span',cls=''){return `<${tag} data-key="${key}"${cls?` class="${cls}"`:''}>${escape(t(key)).replace(/\n/g,'<br>')}</${tag}>`;}
const eyebrow=key=>txt(key,'span','eyebrow');
const heading=(first,second)=>`<h2>${txt(first)}<br>${txt(second)}</h2>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));return true;}catch{toast('Speichern im Browser nicht möglich. Bitte den Entwurf exportieren.');return false;}}
function applyState(){document.documentElement.lang=state.language;document.documentElement.style.setProperty('--gold',state.accent);$('#language').value=state.language;$('#accent').value=state.accent;$('#edit-notes').value=state.notes;}
function homeMarkup(){return `
 <section class="hero" id="start"><div class="hero-visual" aria-hidden="true"><img src="/hero-reference.jpg" alt="" width="1348" height="926"></div><div class="hero-copy">${eyebrow('heroEyebrow')}<h1>ELEVEN<br>GLOBAL<i>.</i></h1>${heading('heroFirst','heroSecond')}${txt('heroBody','p')}${txt('regions','p','regions')}<div class="hero-buttons"><a href="#kontakt" data-audience="player" class="button primary">${txt('playersCta')}</a><a href="#kontakt" data-audience="club" class="button outline">${txt('clubsCta')}</a></div></div><div class="hero-bottom"><a href="#agentur">↓ ${txt('discover')}</a>${txt('heroFoot')}<span>EST. 2026</span></div></section>
 <section class="section" id="agentur"><div class="two-col"><div class="agency-copy">${eyebrow('agencyEyebrow')}${heading('agencyFirst','agencySecond')}${txt('agencyBody1','p')}${txt('agencyBody2','p')}<div class="signature"><strong aria-hidden="true">11</strong><div>Sevket Baykurd${txt('founderRole','small')}</div></div></div><div class="agency-art"><div class="crop agency-crop"><img src="/agency-reference.jpg" alt="Fußballspieler am Spielfeldrand bei Abendlicht" width="1348" height="926" loading="lazy"></div><div class="art-caption"><strong aria-hidden="true">11</strong><span>ONE GAME.<br>A WORLD OF POSSIBILITIES.</span></div></div></div><div class="values">${[1,2,3].map(i=>`<div><i>+</i>${txt('value'+i)}</div>`).join('')}</div></section>
 <section class="section tinted" id="leistungen"><div class="two-col"><div class="services-intro">${eyebrow('servicesEyebrow')}${heading('servicesFirst','servicesSecond')}${txt('servicesIntro','p')}<a class="text-link" href="#kontakt">${txt('contactCta')}　↗</a></div><div class="services-list">${[1,2,3,4,5].map(i=>`<details name="services"${i===1?' open':''}><summary><span class="number">0${i}</span>${txt('service'+i)}</summary><div class="service-content">${i===1?`${eyebrow('service1Label')}${txt('service1Lead','p')}`:''}${txt('service'+i+'Body','p')}${i===1?`<ul>${[1,2,3].map(j=>txt('service1Item'+j,'li')).join('')}</ul>`:''}</div></details>`).join('')}</div></div></section>
 <section class="section" id="maerkte">${eyebrow('marketsEyebrow')}<div class="section-heading">${heading('marketsFirst','marketsSecond')}${txt('marketsIntro','p')}</div><div class="markets-tabs" role="tablist" aria-label="Zielmärkte">${[1,2,3,4].map(i=>`<button role="tab" id="market-tab-${i}" aria-controls="market-panel" data-market="${i}" aria-selected="${i===market}" tabindex="${i===market?0:-1}"><small>0${i}</small>　${txt('market'+i)}</button>`).join('')}</div><div id="market-panel" class="market-detail" role="tabpanel" aria-labelledby="market-tab-${market}"><div class="crop map-crop"><img src="/markets-reference.jpg" alt="Zielmarktübersicht: Deutschland, Türkei, Europa und Golfstaaten" width="1348" height="926" loading="lazy"></div><div class="market-copy">${marketMarkup()}</div></div></section>
 <section class="section tinted" id="ansatz">${eyebrow('approachEyebrow')}<div class="section-heading">${heading('approachFirst','approachSecond')}${txt('approachIntro','p')}</div><div class="steps">${[1,2,3,4].map(i=>`<article class="step"><span class="eyebrow">0${i}</span>${txt('step'+i,'h3')}${txt('step'+i+'Body','p')}<div class="step-result">✓　${txt('step'+i+'Result')}</div></article>`).join('')}</div>${txt('approachNote','p','approach-note')}</section>
 <section class="section contact" id="kontakt"><div class="two-col"><div class="contact-copy">${eyebrow('contactEyebrow')}${heading('contactFirst','contactSecond')}${txt('contactIntro','p')}<div class="contact-meta">${txt('location')}<br>${txt('discretion')}<br><a href="mailto:contact@eleven-global.com">contact@eleven-global.com</a><br><a href="tel:+491786394229">+49 178 639 4229</a></div><div class="contact-person">${eyebrow('contactPerson')}<h3>Sevket Baykurd</h3>${txt('founderRole','p')}</div></div><form id="contact-form" class="form-grid"><label class="field">${txt('nameLabel')} *<input name="name" autocomplete="name" required maxlength="120"></label><label class="field">${txt('emailLabel')} *<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label class="field">${txt('roleLabel')} *<select name="role" required><option value="">—</option><option value="player">${escape(t('rolePlayer'))}</option><option value="coach">${escape(t('roleCoach'))}</option><option value="club">${escape(t('roleClub'))}</option><option value="other">${escape(t('roleOther'))}</option></select></label><label class="field">${txt('orgLabel')}<input name="organisation" autocomplete="organization" maxlength="160"></label><label class="field full">${txt('messageLabel')} *<textarea name="message" rows="4" placeholder="${escape(t('messagePlaceholder'))}" maxlength="5000" required></textarea></label>${txt('messageHelp','span','form-note full')}<label class="check full"><input name="consent" type="checkbox" required>${txt('consent')}</label><button class="button primary full" type="submit">${txt('send')}</button>${txt('formNote','span','form-note full')}<div class="form-result full" role="status" aria-live="polite"></div></form></div></section>`;}
function marketMarkup(){return `${eyebrow('market'+market+'Label')}${txt('market'+market+'Title','h3')}${txt('market'+market+'Body','p')}${txt('considerations','span','eyebrow')}<ul>${[1,2,3].map(i=>txt('marketItem'+i,'li')).join('')}</ul>`;}
function legalMarkup(slug){const page=legal[slug];const note={de:'Referenztext aus dem PDF vom 08.09.2026 – nicht rechtlich geprüft. In diesem Mockup findet kein Formularversand statt; Entwurfsänderungen werden nur lokal im Browser gespeichert. Vor dem Echtbetrieb an die tatsächliche Umsetzung anpassen.',en:'German reference text from the PDF dated 8 September 2026; not legally reviewed. This mockup sends no enquiries. Draft changes are stored in this browser only. Adapt these texts before production use.',tr:'8 Eylül 2026 tarihli PDF’den Almanca referans metin; hukuki inceleme yapılmamıştır. Bu mockup talep göndermez. Taslak değişiklikleri yalnızca bu tarayıcıda saklanır. Canlı kullanım öncesinde metinler uyarlanmalıdır.'};return `<article class="legal-page"><span class="eyebrow">${escape(page.eyebrow)}</span>${txt(`legal.${slug}.title`,'h1')}${txt(`legal.${slug}.intro`,'p','lead')}<p class="legal-notice">${note[state.language]}</p>${page.rows.map((row,i)=>`<section class="legal-row">${txt(`legal.${slug}.${i}.label`,'h2')}${txt(`legal.${slug}.${i}.body`,'p')}</section>`).join('')}</article>`;}
const slug=location.pathname.replace(/^\/+|\/+$/g,'').replace(/\/index\.html$/,'');
const isLegal=Object.hasOwn(legal,slug);
function render(){applyState();const nav=[['agentur','navAgency'],['leistungen','navServices'],['maerkte','navMarkets'],['ansatz','navApproach'],['kontakt','navContact']];$('#navigation').innerHTML=isLegal?`<a href="/">← ${txt('back')}</a>`:nav.map(([id,key])=>`<a href="#${id}">${txt(key)}</a>`).join('');$('.header-cta').textContent=t('contactCta');$('#main').innerHTML=isLegal?legalMarkup(slug):homeMarkup();$('#footer').innerHTML=`<p>© 2026 Eleven Global. ${txt('rights')}<br>Eine Marke der STARKS Betriebs GmbH</p><div class="legal-links"><a href="/impressum/">${txt('legalImprint')}</a><a href="/datenschutz/">${txt('legalPrivacy')}</a><a href="/agb/">${txt('legalTerms')}</a></div>`;document.title=`${isLegal?legal[slug].title+' | ':''}Eleven Global · Website-Mockup`;$('#contact-form')?.addEventListener('submit',event=>{event.preventDefault();if(event.currentTarget.reportValidity())$('.form-result').textContent=t('formSuccess');});}
function updateMarket(i,focus=false){if(!Number.isInteger(i)||i<1||i>4)throw Error('Ungültiger Markt.');market=i;document.querySelectorAll('[data-market]').forEach(el=>{el.setAttribute('aria-selected',String(Number(el.dataset.market)===i));el.tabIndex=Number(el.dataset.market)===i?0:-1;});$('.market-copy').innerHTML=marketMarkup();$('#market-panel').setAttribute('aria-labelledby',`market-tab-${i}`);if(focus)$(`#market-tab-${i}`).focus();}
function replaceText(key,value){if(!knownKeys.has(key)||typeof value!=='string'||value.length>10000)throw Error('Ungültiger Text.');const lang=key.startsWith('legal.')?'de':state.language;state.overrides[lang][key]=value;document.querySelectorAll('[data-key]').forEach(el=>{if(el.dataset.key===key){el.replaceChildren(...value.split('\n').flatMap((line,i)=>i?[document.createElement('br'),document.createTextNode(line)]:[document.createTextNode(line)]));}});return persist();}
$('#language').addEventListener('change',event=>{state.language=event.target.value;persist();render();});
$('.menu-toggle').addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',String(open));});
$('#edit-toggle').addEventListener('click',()=>{editing=!editing;document.body.classList.toggle('editing',editing);$('#edit-toggle').setAttribute('aria-pressed',String(editing));$('#edit-toggle').textContent=editing?'Bearbeiten beenden':'Texte bearbeiten';if(editing)toast('Klicke auf einen markierten Text, um ihn zu ändern.');});
document.addEventListener('click',event=>{const target=event.target.closest('[data-key]');if(editing&&target){event.preventDefault();event.stopPropagation();selectedKey=target.dataset.key;$('#text-value').value=t(selectedKey);$('#text-editor').showModal();$('#text-value').focus();return;}const marketButton=event.target.closest('[data-market]');if(marketButton)updateMarket(Number(marketButton.dataset.market));const audience=event.target.closest('[data-audience]');if(audience&&$('#contact-form'))$('#contact-form').elements.role.value=audience.dataset.audience;if(event.target.closest('nav a')){$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');}},true);
document.addEventListener('keydown',event=>{const tab=event.target.closest('[data-market]');if(!tab)return;const keys=['ArrowLeft','ArrowRight','Home','End'];if(keys.includes(event.key)){event.preventDefault();const i=Number(tab.dataset.market);updateMarket(event.key==='Home'?1:event.key==='End'?4:event.key==='ArrowRight'?(i%4)+1:((i+2)%4)+1,true);}});
$('#text-form').addEventListener('submit',event=>{event.preventDefault();const saved=replaceText(selectedKey,$('#text-value').value);$('#text-editor').close();if(saved)toast('Text in diesem Browser gespeichert.');});$('#text-close').addEventListener('click',()=>$('#text-editor').close());
$('#settings-open').addEventListener('click',()=>$('#editor').showModal());
$('#accent').addEventListener('input',event=>{state.accent=event.target.value;document.documentElement.style.setProperty('--gold',state.accent);persist();});$('#edit-notes').addEventListener('input',event=>{state.notes=event.target.value.slice(0,10000);persist();});
$('#export').addEventListener('click',()=>{const content={...state,project:'Eleven Global',exportedAt:new Date().toISOString(),basis:'Eleven_Global_Webseiten-Mockup_2026-09-08.pdf',status:'Editable mockup; no email sending; legal text not reviewed',resolvedContent:Object.fromEntries(Object.entries(dictionaries).map(([lang,copy])=>[lang,{...de,...copy,...state.overrides[lang]}]))};const url=URL.createObjectURL(new Blob([JSON.stringify(content,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='Eleven_Global_Mockup_Entwurf.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Entwurf exportiert. Du kannst die Datei hier wieder hochladen.');});
$('#import').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Die Datei ist zu groß.');const next=validateState(JSON.parse(await file.text()));if(!confirm('Die aktuellen lokalen Änderungen durch diesen Entwurf ersetzen?'))return;state=next;const saved=persist();render();if(saved)toast('Entwurf importiert und in diesem Browser gespeichert.');}catch(error){toast(error.message||'Die Datei konnte nicht importiert werden.');}finally{event.target.value='';}});
$('#reset').addEventListener('click',()=>{if(!confirm('Alle eigenen Text-, Farb- und Notizänderungen in diesem Browser zurücksetzen? Exportiere sie vorher, wenn du sie behalten möchtest.'))return;const language=state.language;state=structuredClone(fallback);state.language=language;persist();render();toast('Der ursprüngliche Mockup-Entwurf ist wiederhergestellt.');});
render();if(storageBlocked)toast('Lokaler Entwurf konnte nicht geladen werden. Exportiere Änderungen zur Sicherung.');
if(location.hash&&!isLegal)setTimeout(()=>{document.getElementById(location.hash.slice(1))?.scrollIntoView();},50);
// Same state mutations as the visible editor, when the browser supports WebMCP.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_mockup_draft',title:'Mockup-Entwurf lesen',description:'Read the current browser-local Eleven Global draft and editable text keys.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({language:state.language,accent:state.accent,notes:state.notes,overrides:structuredClone(state.overrides),content:Object.fromEntries([...knownKeys].map(key=>[key,t(key)]))})});register({name:'update_mockup_texts',title:'Mockup-Texte ändern',description:'Update a batch of visible draft texts and save in this browser only. Does not publish or send anything.',inputSchema:{type:'object',properties:{changes:{type:'array',minItems:1,maxItems:50,items:{type:'object',properties:{key:{type:'string'},text:{type:'string',maxLength:10000}},required:['key','text'],additionalProperties:false}}},required:['changes'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||!Array.isArray(input.changes)||input.changes.length<1||input.changes.length>50||input.changes.some(c=>!c||!knownKeys.has(c.key)||typeof c.text!=='string'||c.text.length>10000))throw Error('Invalid text changes.');let saved=true;for(const c of input.changes)saved=replaceText(c.key,c.text)&&saved;return{updated:input.changes.length,savedLocally:saved,published:false};}});addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
